	clock := &fakeClock{t: time.Unix(0, 0)}
	tb, _ := NewTokenBucket(100, 10, clock)
	var wg sync.WaitGroup
	var allowed int64
	var mu sync.Mutex
	for i := 0; i < 200; i++ {
